starter_code:
#include <iostream>

void modify(int value)
{
    value = 20;
}

int main()
{
    int value = 10;
    modify(value);
    std::cout << value << '\n';

    return 0;
}

reference_solution:
#include <iostream>

void modify(int& value)
{
    value = 20;
}

int main()
{
    int value = 10;
    modify(value);
    std::cout << value << '\n';

    return 0;
}
